"use server";

import { z } from "zod";
import { Prisma } from "@prisma/client";
import { db } from "./db";

export type SubscribeResult = {
  ok: boolean;
  status: "subscribed" | "already" | "error";
  message: string;
};

const emailSchema = z.email();

/**
 * Add an email to the newsletter list. Idempotent: a repeat submission of the
 * same (case-insensitive) address is reported as "already" rather than an error,
 * and the unique constraint is the source of truth against races. No external
 * ESP — we just persist the lead for later export.
 */
export async function subscribe(
  email: string,
  source = "landing",
): Promise<SubscribeResult> {
  const raw = typeof email === "string" ? email.trim().toLowerCase() : "";

  if (!raw) {
    return { ok: false, status: "error", message: "Please enter your email address." };
  }
  if (raw.length > 200) {
    return { ok: false, status: "error", message: "That email address is too long." };
  }

  const parsed = emailSchema.safeParse(raw);
  if (!parsed.success) {
    return { ok: false, status: "error", message: "That doesn’t look like a valid email." };
  }
  const value = parsed.data;

  const cleanSource = (typeof source === "string" ? source.trim() : "").slice(0, 60) || "landing";

  const existing = await db.newsletterSubscriber.findUnique({ where: { email: value } });
  if (existing) {
    return {
      ok: true,
      status: "already",
      message: "You’re already on the list — thanks for sticking around!",
    };
  }

  try {
    await db.newsletterSubscriber.create({ data: { email: value, source: cleanSource } });
  } catch (err) {
    // Unique-constraint race: another request inserted the same email first.
    if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === "P2002") {
      return {
        ok: true,
        status: "already",
        message: "You’re already on the list — thanks for sticking around!",
      };
    }
    return {
      ok: false,
      status: "error",
      message: "Something went wrong. Please try again in a moment.",
    };
  }

  return {
    ok: true,
    status: "subscribed",
    message: "You’re in! We’ll send occasional product news — no spam.",
  };
}

"use client";

import { useState, useTransition } from "react";
import { subscribe, type SubscribeResult } from "@/lib/actions-newsletter";
import { IconMail, IconArrow, IconCheck } from "./icons";

type Variant = "footer" | "inline";

/**
 * Email capture that calls the `subscribe` server action directly. Shows a
 * friendly inline status for success / already-subscribed / validation errors.
 * `variant` only tweaks layout — logic is shared.
 */
export function NewsletterSignup({
  source = "landing",
  variant = "footer",
}: {
  source?: string;
  variant?: Variant;
}) {
  const [email, setEmail] = useState("");
  const [result, setResult] = useState<SubscribeResult | null>(null);
  const [pending, startTransition] = useTransition();

  const succeeded = result?.ok === true;

  function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (pending) return;
    startTransition(async () => {
      const res = await subscribe(email, source);
      setResult(res);
      if (res.ok) setEmail("");
    });
  }

  return (
    <form onSubmit={onSubmit} noValidate className={variant === "inline" ? "mx-auto max-w-md" : "w-full"}>
      <div className="flex flex-col gap-2.5 sm:flex-row">
        <div className="relative flex-1">
          <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-500">
            <IconMail size={18} />
          </span>
          <input
            type="email"
            name="email"
            autoComplete="email"
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="you@example.com"
            aria-label="Email address"
            aria-invalid={result?.ok === false || undefined}
            className="input w-full pl-10"
            disabled={pending}
          />
        </div>
        <button
          type="submit"
          className="btn-primary shrink-0 justify-center px-5 py-2.5"
          disabled={pending}
        >
          {pending ? "Subscribing…" : "Subscribe"}
          {!pending && <IconArrow size={16} />}
        </button>
      </div>

      {result && (
        <p
          className={`mt-2.5 flex items-center gap-1.5 text-sm ${
            succeeded ? "text-emerald-400" : "text-rose-400"
          }`}
          role="status"
          aria-live="polite"
        >
          {succeeded && (
            <span className="flex h-4 w-4 items-center justify-center rounded-full bg-emerald-500/15">
              <IconCheck size={11} />
            </span>
          )}
          {result.message}
        </p>
      )}
    </form>
  );
}

import {
  IconLock,
  IconNvme,
  IconShield,
  IconGlobe,
  IconBolt,
