/**
 * Factual trust/assurance badges. Every item reflects something Nxeon actually
 * offers — no invented certifications, awards, or logos.
 */
const BADGES: { icon: React.ReactNode; label: string; sub: string }[] = [
  { icon: <IconLock />, label: "Free SSL", sub: "Let’s Encrypt certificates" },
  { icon: <IconNvme />, label: "NVMe SSD", sub: "Enterprise ZFS-mirrored storage" },
